export const Intent = z.enum([
    'elicit_options',
    'add_option',
    'challenge_frame',
    'challenge_assumption',
    'outside_view',
    'pre_mortem',
    'elicit_risks',
    'estimate_help',
    'mitigation_help',
    'define_success',
    'discuss',
]);
